from django.core.management.base import BaseCommand
from api.models import Product,CaseStudy,Insight
class Command(BaseCommand):
 def handle(self,*args,**kwargs):
  for n,c,d,o in [("AQVYRON","Business Intelligence","Intelligent Business Intelligence & Data Analytics System.",1),("NEXORA","AI / SaaS","A modern AI SaaS experience for digital businesses.",2),("ESTORA","Real Estate","A premium digital experience for modern real estate.",3)]: Product.objects.update_or_create(slug=n.lower(),defaults={"name":n,"category":c,"description":d,"order":o})
  for t,c,s,ch,a,tech in [("AQVYRON","Business Intelligence","Turning business data into actionable intelligence.","Complex analytics workflows.","Unified analytics and decision-support UX.","React, TypeScript, Django, PostgreSQL"),("NEXORA","AI / SaaS","A premium SaaS experience designed around AI workflows.","Communicating a complex product simply.","Focused product storytelling and responsive UI.","React, TypeScript, Vite"),("ESTORA","Real Estate","A premium property discovery experience.","Balancing rich property content with speed and clarity.","Search, property detail and agent experiences.","React, TypeScript, Vite")]: CaseStudy.objects.update_or_create(slug=t.lower(),defaults={"title":t,"category":c,"summary":s,"challenge":ch,"approach":a,"technology":tech})
  for t,c,e,s in [("Designing AI products people can actually use","AI","Clarity, trust and product UX in AI systems.","designing-ai-products"),("From raw data to business intelligence","Data","How product thinking can make analytics more useful.","raw-data-to-business-intelligence"),("Building a modern SaaS frontend","Engineering","A clean architecture for responsive SaaS interfaces.","modern-saas-frontend")]: Insight.objects.update_or_create(slug=s,defaults={"title":t,"category":c,"excerpt":e})
  self.stdout.write(self.style.SUCCESS("BIAvanta demo content seeded."))
